-- Feature house ads: KChat suggesting its own features ("Suggested for you", not "Sponsored").
-- 1. `feature` tags a house ad with the feature it promotes, so /ads/slots can lean towards features
--    this person hasn't tried yet (and write the reason into "Why am I seeing this?").
-- 2. The first painted house ads (20261029000100) are ended, not deleted, so their stats stay.
-- 3. Eight feature ads with real app captures, each deep-linking into the feature.
-- Safe to re-run.

alter table public.ad_campaigns add column if not exists feature text;

update public.ad_campaigns
   set status = 'ended', updated_at = now()
 where is_house = true and status <> 'ended'
   and media_url in (
     'https://api.kiongozi.org/ads-media/ad_city.jpg', 'https://api.kiongozi.org/ads-media/ad_ai.jpg',
     'https://api.kiongozi.org/ads-media/ad_week.jpg', 'https://api.kiongozi.org/ads-media/ad_story.jpg');

insert into public.ad_campaigns
  (advertiser_name, advertiser_avatar_url, headline, body, media_url, media_type, width, height, placeholder,
   cta_label, cta_url, is_house, status, weight, frequency_hours, feature, why_text)
select v.* from (values
  ('KChat', 'https://api.kiongozi.org/ads-media/kchat-avatar.png', 'Got something to say? Start a baraza.', 'Live audio rooms where one person holds the talking stick at a time. Pick a topic, pass the stick, and KChat writes the minutes after.', 'https://api.kiongozi.org/ads-media/feat_baraza.jpg', 'image', 1080, 1350,
   'data:image/jpeg;base64,',
   'Start a baraza', 'kchat://baraza', true, 'active', 6, 24, 'baraza',
   'KChat suggests its own features to help you get more out of the app. Nobody paid for this.'),
  ('KChat', 'https://api.kiongozi.org/ads-media/kchat-avatar.png', 'Mitaa is where the clips are.', 'Short videos from people near you and people you follow. Swipe up for the next one.', 'https://api.kiongozi.org/ads-media/feat_mitaa.jpg', 'image', 1080, 1350,
   'data:image/jpeg;base64,',
   'Open Mitaa', 'kchat://mitaa', true, 'active', 5, 24, 'mitaa',
   'KChat suggests its own features to help you get more out of the app. Nobody paid for this.'),
  ('KChat', 'https://api.kiongozi.org/ads-media/kchat-avatar.png', 'Your Week is ready.', 'A few quick slides on your week on KChat: your best numbers, your biggest fan and who you were this week. Share the card if it slaps.', 'https://api.kiongozi.org/ads-media/feat_week.jpg', 'image', 1080, 1350,
   'data:image/jpeg;base64,',
   'See your week', 'kchat://recap', true, 'active', 5, 24, 'week',
   'KChat suggests its own features to help you get more out of the app. Nobody paid for this.'),
  ('KChat', 'https://api.kiongozi.org/ads-media/kchat-avatar.png', 'Can’t agree? Put it to a vote.', 'Add a poll to your story and let your people decide. Votes come in live while it’s up.', 'https://api.kiongozi.org/ads-media/feat_poll.jpg', 'image', 1080, 1350,
   'data:image/jpeg;base64,',
   'Make a poll story', 'kchat://story', true, 'active', 5, 24, 'story',
   'KChat suggests its own features to help you get more out of the app. Nobody paid for this.'),
  ('KChat', 'https://api.kiongozi.org/ads-media/kchat-avatar.png', 'Say it with a voice note.', 'Hold the mic in any chat and talk. Slide to cancel if you change your mind, and every note comes with a transcript.', 'https://api.kiongozi.org/ads-media/feat_voice.jpg', 'image', 1080, 1350,
   'data:image/jpeg;base64,',
   'Open chats', 'kchat://messages', true, 'active', 5, 24, 'voice',
   'KChat suggests its own features to help you get more out of the app. Nobody paid for this.'),
  ('KChat', 'https://api.kiongozi.org/ads-media/kchat-avatar.png', 'Ask Kiongozi AI.', 'Homework, money, jobs, your county budget. Ask in English, Kiswahili or Sheng and get a straight answer.', 'https://api.kiongozi.org/ads-media/feat_ai.jpg', 'image', 1080, 1350,
   'data:image/jpeg;base64,',
   'Ask a question', 'kchat://ai', true, 'active', 5, 24, 'ai',
   'KChat suggests its own features to help you get more out of the app. Nobody paid for this.'),
  ('KChat', 'https://api.kiongozi.org/ads-media/kchat-avatar.png', 'KChat is better with your people.', 'Bring your crew over. Send them your link in one tap.', 'https://api.kiongozi.org/ads-media/feat_invite.jpg', 'image', 1080, 1350,
   'data:image/jpeg;base64,',
   'Invite friends', 'kchat://invite', true, 'active', 4, 24, 'invite',
   'KChat suggests its own features to help you get more out of the app. Nobody paid for this.'),
  ('KChat', 'https://api.kiongozi.org/ads-media/kchat-avatar.png', 'See what Kenya is talking about.', 'Trending tags, live barazas and people worth following, all in Explore.', 'https://api.kiongozi.org/ads-media/feat_explore.jpg', 'image', 1080, 1350,
   'data:image/jpeg;base64,',
   'Open Explore', 'kchat://explore', true, 'active', 4, 24, 'explore',
   'KChat suggests its own features to help you get more out of the app. Nobody paid for this.')
) as v(advertiser_name, advertiser_avatar_url, headline, body, media_url, media_type, width, height, placeholder,
       cta_label, cta_url, is_house, status, weight, frequency_hours, feature, why_text)
where not exists (select 1 from public.ad_campaigns c where c.media_url = v.media_url);
